:root {
  --bg-card: #2b1f17;
  --bg-header: #3d2a1e;
  --bg-body: #f7f0eb;
  --bg-phase: #ede0d6;
  --accent-fire: #e05c1a;
  --accent-gold: #d4942a;
  --accent-warm: #c47a3b;
  --bar-preheat: #f5b97a;
  --bar-ramp: #e05c1a;
  --bar-soak: #c0392b;
  --bar-cool: #6baed6;
  --text-light: #f7ede3;
  --text-muted: #b89a84;
  --text-dark: #2b1f17;
  --text-phase: #5c3d28;
  --badge-bg: #4caf7d;
  --badge-text: #fff;
  --btn-primary-bg: #e05c1a;
  --btn-primary-text: #fff;
  --btn-secondary-bg: #ede0d6;
  --btn-secondary-text: #5c3d28;
  --border-subtle: #5c3d28;
}

.kiln-card {
  width: 480px;
  background: var(--bg-card);
  border-radius: 14px;
  overflow: hidden;
  font-size: 14px;
}

.kiln-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 2px solid var(--border-subtle);
}

.kiln-title-block {
  display: flex;
  align-items: center;
  gap: 12px;
}

.kiln-icon {
  font-size: 28px;
  line-height: 1;
}

.kiln-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-light);
  margin: 0;
  line-height: 1.2;
}

.kiln-studio {
  font-size: 12px;
  color: var(--text-muted);
  margin: 2px 0 0;
}

.kiln-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.kiln-body {
  background: var(--bg-body);
  padding: 16px 18px;
}

.kiln-meta {
  display: flex;
  gap: 0;
  margin-bottom: 14px;
  border: 1px solid var(--bg-phase);
  border-radius: 8px;
  overflow: hidden;
}

.meta-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px;
  background: var(--bg-phase);
  border-right: 1px solid var(--bg-body);
}

.meta-item:last-child {
  border-right: none;
}

.meta-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-warm);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 4px;
}

.meta-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-dark);
}

.phase-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.phase {
  display: flex;
  align-items: center;
  gap: 10px;
}

.phase-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-phase);
  width: 72px;
  flex-shrink: 0;
}

.phase-bar-wrap {
  flex: 1;
  height: 10px;
  background: var(--bg-phase);
  border-radius: 6px;
  overflow: hidden;
}

.phase-bar {
  height: 100%;
  border-radius: 6px;
}

.phase--preheat .phase-bar { background: var(--bar-preheat); }
.phase--ramp .phase-bar    { background: var(--bar-ramp); }
.phase--soak .phase-bar    { background: var(--bar-soak); }
.phase--cool .phase-bar    { background: var(--bar-cool); }

.phase-temp {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-phase);
  width: 52px;
  text-align: right;
  flex-shrink: 0;
}

.kiln-footer {
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  border-top: 1px solid var(--border-subtle);
}

.kiln-pieces {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.pieces-label {
  font-size: 12px;
  color: var(--text-muted);
}

.pieces-count {
  font-size: 22px;
  font-weight: 800;
  color: var(--accent-gold);
}

.kiln-actions {
  display: flex;
  gap: 8px;
}

.btn {
  padding: 7px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  border: none;
  cursor: pointer;
}

.btn--primary {
  background: var(--btn-primary-bg);
  color: var(--btn-primary-text);
}

.btn--secondary {
  background: var(--btn-secondary-bg);
  color: var(--btn-secondary-text);
}
